const schema = { type: "object", required: ["id"], properties: { id: { type: "number" } } };
test("tv4", () => {
  expect(tv4.validate({ id: 1 }, schema)).to.be.true;
  expect(require('tv4').validate({}, schema)).to.be.false;
  expect(tv4.error.message).to.include("required property 'id'");
});
test("ajv", () => {
  const Ajv = require('ajv');
  const validate = new Ajv().compile(schema);
  expect(validate({ id: "x" })).to.be.false;
  expect(validate.errors[0].message).to.equal("data.id should be number");
  expect(new Ajv().validate(schema, { id: 2 })).to.be.true;
});
